fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and go to Data Explorer, then its Data section. Open the 'Products' entity via the LEFT sidebar 'Search record types...' box (type 'Products', then click the entry named exactly 'Products' (not 'Product Categories', 'Product Prices', 'Product Types' or 'Event Products'); or navigate to http://localhost:4200/app/data-explorer/Data?entity=MJ_BizApps_Orders:%20Products) and wait for the records grid to render. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) cards-view — open the view-type switcher dropdown in the view toolbar (a button showing the current type like 'Grid' with a chevron) and choose 'Cards' so the records re-render as a card grid; (2) view-selector-select — open the saved-view selector (layer-group icon labeled with the current view name or '(Default)'), confirm the 'Saved Views' panel lists at least a '(Default)' entry, and click it to apply; (3) create-saved-view — open the saved-view selector again, click '+ New Saved View' in the panel footer, and in the View Studio that opens type a unique name such as 'CU Grid Test 4821' into the 'Enter a name for this view...' box and click 'Create View'; confirm the new view becomes the active view (its name shows on the selector, or it is listed under 'My Views'); (4) timeline-view — open the view-type switcher again and, if 'Timeline' is offered, select it and confirm a chronological timeline layout (if Timeline is not offered, selecting another type such as Cards and seeing the view re-render is acceptable); (5) view-open-in-tab — make sure the saved view you created in step 3 is the active view (its name shows on the saved-view selector; pick it from the selector if not), then use the button to the right of the selector: the 'Open this view in a new tab' icon button (external-link icon) that only appears while a saved view is selected, never for '(Default)' (each saved-view card in the 'Saved Views' panel also has an 'Open in Tab' action that appears on hover) — and confirm the view opens as its own workspace tab showing the entity's records; (6) reset-view — go back to the Products records in the Data tab, make a change to the view (click a column header to sort, or switch the view type), then open the saved-view selector and click the '(Default)' entry, confirming the selector shows '(Default)' again and the records reload in the default layout. Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "cards-view",
      "instruction": "switch the view type to Cards on the Products grid",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/data-explorer/Data"
        }
      ],
      "visualCriteria": [
        "The view-type switcher lists more than one type including 'Cards', and after selecting Cards the records re-render as a card grid instead of the tabular AG-Grid (or a valid empty-state for that view)"
      ]
    },
    {
      "name": "view-selector-select",
      "instruction": "open the saved-view selector and apply the (Default) view",
      "visualCriteria": [
        "Clicking the saved-view selector opens a 'Saved Views' panel listing at least a '(Default)' entry, and selecting a view applies it — a check indicator appears on the chosen view and the grid reloads (or a valid empty-state renders)"
      ]
    },
    {
      "name": "create-saved-view",
      "instruction": "create a new saved view via '+ New Saved View' and confirm it becomes active",
      "visualCriteria": [
        "Clicking '+ New Saved View' opens the View Studio with an editable view-name field, and after 'Create View' the newly named view becomes the selected view (name shown on the selector button) or appears under 'My Views'"
      ]
    },
    {
      "name": "timeline-view",
      "instruction": "switch the view type to Timeline (or an alternate type) and confirm re-render",
      "visualCriteria": [
        "The view-type switcher lists multiple types; if 'Timeline' is offered, selecting it renders a chronological timeline layout — otherwise an alternate type (e.g. Cards) is selectable and the view re-renders, or a valid empty-state shows"
      ]
    },
    {
      "name": "view-open-in-tab",
      "instruction": "open a saved view in its own tab via the Open-in-Tab action",
      "visualCriteria": [
        "With a saved view selected, the 'Open this view in a new tab' button (external-link icon beside the saved-view selector) — or a view card's 'Open in Tab' action in the Saved Views panel — opens that view as its own workspace tab showing the entity's records (or a valid empty-state), and the app stays responsive"
      ]
    },
    {
      "name": "reset-view",
      "instruction": "change the view, then select (Default) and confirm revert",
      "visualCriteria": [
        "After a sort or view-type change, selecting the '(Default)' entry in the saved-view selector returns the selector label to '(Default)' and the records reload in the default layout"
      ]
    }
  ]
}
